#include "notify/config.hpp"
#include <fstream>
#include <filesystem>
#include <stdexcept>
namespace notify {
BuildConfig BuildConfig::load(const std::wstring& p){std::ifstream f(std::filesystem::path(p),std::ios::binary);if(!f)throw std::runtime_error("cannot open config");std::string s((std::istreambuf_iterator<char>(f)),{});BuildConfig c;c.root_=json::parse(s);c.validate();return c;}
const json::Value* BuildConfig::field(std::string_view n)const{return root_.find(n);}
std::string BuildConfig::text(std::string_view n,std::string f)const{auto x=field(n);auto v=x?x->find("value"):nullptr;if(!v)return f;if(auto s=std::get_if<std::string>(&v->data))return*s;if(auto i=std::get_if<std::int64_t>(&v->data))return std::to_string(*i);return f;}
long long BuildConfig::integer(std::string_view n,long long f)const{auto x=field(n);auto v=x?x->find("value"):nullptr;if(!v||v->is_null())return f;double d=v->number_or(-1);if(d<0||d>9e15||d!=(long long)d)throw std::runtime_error("invalid integer config field");return (long long)d;}
State BuildConfig::state(std::string_view n)const{auto x=field(n);auto v=x?x->find("state"):nullptr;auto s=v?v->string_or():"unset";if(s=="configured")return State::configured;if(s=="derived")return State::derived;if(s=="measured")return State::measured;if(s=="provided")return State::provided;return State::unset;}
bool BuildConfig::is_set(std::string_view n)const{auto x=field(n);auto s=x?x->find("state"):nullptr;auto v=x?x->find("value"):nullptr;return s&&s->string_or()!="unset"&&v&&!v->is_null();}
void BuildConfig::validate()const{auto t=integer("failure_threshold",0),w=integer("max_workers",0),c=integer("connect_timeout_ms",0),p=integer("max_photo_bytes",0),r=integer("retry_base_ms",0);if(t<3||t>7||w<1||w>256||c<=0||p<=0||r<=0)throw std::runtime_error("invalid build configuration bounds");if(integer("card_count",0)!=5)throw std::runtime_error("card_count must equal five");for(const auto* key:{"card_labels","phone_input_state","code_input_state","connect_action"})if(state(key)!=State::unset||is_set(key))throw std::runtime_error(std::string("screen field must remain unset: ")+key);auto root=std::get_if<json::Value::Object>(&root_.data);if(!root)throw std::runtime_error("config root must be object");for(const auto&[name,item]:*root){auto value=item.find("value"),state=item.find("state"),source=item.find("source_build"),kind=item.find("kind"),note=item.find("note");if(!value||!state||!source||!kind||!note)throw std::runtime_error("config field schema invalid: "+name);auto st=state->string_or();auto kd=kind->string_or();if(st.empty()||kd.empty())throw std::runtime_error("empty config state/kind");if(st=="unset"&&!value->is_null())throw std::runtime_error("unset config value must be null: "+name);if(st=="measured"&&(value->is_null()||source->is_null()))throw std::runtime_error("measured config needs value and source_build: "+name);if(kd!="client_field"&&kd!="literal"&&kd!="file_offset"&&kd!="rva"&&kd!="runtime_va")throw std::runtime_error("invalid config kind: "+name);}}
}

